import java.util.Scanner;

class Animal {
    String name;

    Animal(String name) {
        this.name = name;
    }

    void speak() {
        System.out.println(name + "：……");
    }
}

class Cat extends Animal {
    Cat(String name) {
        super(name);
    }

    @Override
    void speak() {
        System.out.println(name + "：喵～");
    }

    void sleep() {
        System.out.println(name + "睡着了，呼噜呼噜");
    }
}

class Dog extends Animal {
    Dog(String name) {
        super(name);
    }

    @Override
    void speak() {
        System.out.println(name + "：汪！");
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Animal a = new Cat("{name}");
        Animal b = new Dog("{dog}");
        a.speak();
        b.speak();
        if (a instanceof Cat) {
            Cat c = (Cat) a;
            for (int i = 0; i < n; i++) {
                c.sleep();
            }
        }
    }
}
